{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "keep",
  "supportive_card_ids": ["C18","C28","C08","C05","C03","C06","C07","C13","C11","C19","C43","C49","C51","C72","C74","C69","C73","C76","C70","C67","C65","C71","C68"],
  "contradictory_card_ids": ["C45","C47","C52"],
  "prediction_basis_card_ids": ["C18","C28","C08","C05","C03","C06","C07","C13","C11","C19"],
  "claims": [
    {
      "claim": "Measured oral bioavailability for nucleoside analogs in the L1 gold contexts is at or above 20%: emtricitabine 92% (C18, C28), stavudine 61-78% (C08), zidovudine 61% (C05), and didanosine 22-35% across doses and formulations (C03, C06, C07, C13, C11, C19). These are the most endpoint-direct records and support F >= 20% for the query as a polar ribonucleoside analog.",
      "card_ids": ["C18","C28","C08","C05","C03","C06","C07","C13","C11","C19"]
    },
    {
      "claim": "L4 close analogs ribavirin and levovirin show low Caco-2 Papp (C45, C47) but high solubility (C43, C49, C51); C47 explicitly cautions that low Papp may reflect limited hCNT2 expression, so this is not affirmative evidence of F < 20%. Gemcitabine low Papp (C52) is a less transferable deoxycytidine analog.",
      "card_ids": ["C45","C47","C43","C49","C51","C52"]
    },
    {
      "claim": "L6 hepatic-clearance records for nucleoside analogs show no major CYP metabolism for GS-441524 (C72, C74) and low intrinsic glucuronidation clearance for zidovudine in human liver microsomes (C69, C73, C76, C70, C67, C65, C71, C68), indicating limited presystemic hepatic loss. The favipiravir aldehyde-oxidase record (C66) is rat cytosol, non-nucleoside, and low CLint, so it does not transfer as negative evidence.",
      "card_ids": ["C72","C74","C69","C73","C76","C70","C67","C65","C71","C68","C66"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C72","C74","C69","C73","C76","C70","C67","C65","C71","C68"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query or its exact 5-hydroxyimidazole-4-carboxamide riboside scaffold.",
    "No query-specific permeability, nucleoside-transporter, efflux, or intestinal-metabolism data exist; L4/L5 data are for analogs and structurally unrelated glycosides.",
    "Caco-2 low permeability may underrepresent in vivo transporter-mediated absorption (C47), so low Papp is not equivalent to low F.",
    "No human hepatic clearance or metabolite identification data exist for the query; L6 data are for other nucleosides (AZT, GS-441524) and favipiravir.",
    "It is unknown whether the ionized 5-hydroxy group (neutral fraction 0.04) impairs nucleoside transporter recognition or increases glucuronide/renal clearance."
  ],
  "decision_summary": "L6 hepatic-clearance records for nucleoside analogs are supportive of limited presystemic hepatic loss and do not overturn the prior high prediction. The most endpoint-direct evidence remains measured F >= 20% for multiple nucleoside analogs, while L4 low Caco-2 permeability for ribavirin/levovirin carries a transporter-expression caveat. Prediction remains high with low confidence."
}

